export const getGetIrocInvoiceShippingRatesUrl = (id: number,
    params: GetIrocInvoiceShippingRatesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/iroc/invoices/${id}/shipping-rates?${stringifiedParams}` : `/api/iroc/invoices/${id}/shipping-rates`
}

